func (valSet *defaultSet) AddValidator(address common.Address, blsPublicKey []byte) bool {
	valSet.validatorMu.Lock()
	defer valSet.validatorMu.Unlock()
	for _, v := range valSet.validators {
		if v.Address() == address {
			return false
		}
	}
	valSet.validators = append(valSet.validators, New(address, blsPublicKey))
	return true
}

func (valSet *defaultSet) RemoveValidator(address common.Address) bool {
	valSet.validatorMu.Lock()
	defer valSet.validatorMu.Unlock()

	for i, v := range valSet.validators {
		if v.Address() == address {
			valSet.validators = append(valSet.validators[:i], valSet.validators[i+1:]...)
			return true
		}
	}
	return false
}

// set timeout based on the round number
cfg := c.config.GetConfig(c.current.Sequence())
baseTimeout := time.Duration(cfg.RequestTimeout) * time.Millisecond
round := c.current.Round().Uint64()
maxRequestTimeout := time.Duration(cfg.MaxRequestTimeoutSeconds) * time.Second

// If the upper limit of the request timeout is capped by small maxRequestTimeout, round can be a quite large number,
// which leads to float64 overflow, making its value negative or zero forever after some point.
// In this case we cannot simply use math.Pow and have to implement a safeguard on our own, at the cost of performance (which is not important in this case).
var timeout time.Duration
if maxRequestTimeout > time.Duration(0) {
	timeout = baseTimeout
	for i := uint64(0); i < round; i++ {
		timeout = timeout * 2
		if timeout > maxRequestTimeout {
			timeout = maxRequestTimeout
			break
		}
	}
	// prevent log storm when unexpected overflow happens
	if timeout < baseTimeout {
		c.currentLogger(true, nil).Warn("WBFT: Possible request timeout overflow detected, setting timeout value to maxRequestTimeout",
			"timeout", timeout.Seconds(),
			"max_request_timeout", maxRequestTimeout.Seconds(),
		)
		timeout = maxRequestTimeout
	}

func (rcs *roundChangeSet) higherRoundMessages(round *big.Int) int {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	addresses := make(map[common.Address]struct{})
	for k, rms := range rcs.roundChanges {
		if k > round.Uint64() {
			for addr := range rms.messages {
				addresses[addr] = struct{}{}
			}
		}
	}
	return len(addresses)
}

func (rcs *roundChangeSet) getMinRoundChange(round *big.Int) *big.Int {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	var keys []int
	for k := range rcs.roundChanges {
		if k > round.Uint64() {
			keys = append(keys, int(k))
		}
	}
	sort.Ints(keys)
	if len(keys) == 0 {
		return round
	}
	return big.NewInt(int64(keys[0]))
}

func (rcs *roundChangeSet) ClearLowerThan(round *big.Int) {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	for k, rms := range rcs.roundChanges {
		if len(rms.Values()) == 0 || k < round.Uint64() {
			delete(rcs.roundChanges, k)
			delete(rcs.highestPreparedRound, k)
			delete(rcs.highestPreparedBlock, k)
			delete(rcs.prepareMessages, k)
		}
	}
}

func hasQuorumOfRoundChangeMessagesForNil(roundChangeMessages []*wbfmessage.SignedRoundChangePayload, quorumSize int) error {
	nilCount := 0
	for _, m := range roundChangeMessages {
		log.Trace("WBFT: hasQuorumOfRoundChangeMessagesForNil", "rc", m)
		if (m.PreparedRound == nil || m.PreparedRound.Cmp(common.Big0) == 0) && m.PreparedDigest == (common.Hash{}) {
			nilCount++
			if nilCount == quorumSize {
				return nil
			}
		}
	}
	return errors.New("quorum of roundchange messages with nil prepared round not found")
}

func (c *Core) checkValidatorSignature(data []byte, sig []byte, view wbft.View) (common.Address, error) {
	if view.Cmp(c.currentView()) < 0 && c.state == StateAcceptRequest && view.Cmp(&wbft.View{
		Sequence: new(big.Int).Sub(c.current.Sequence(), common.Big1),
		Round:    c.PriorRound(),
	}) == 0 {
		if valSet := c.PriorValidators(); valSet != nil {
			return wbft.CheckValidatorSignature(valSet, data, sig)
		}
	}
	return wbft.CheckValidatorSignature(c.valSet, data, sig)
}

func (c *Core) setState(state State) {
	if c.state != state {
		oldState := c.state
		c.state = state
		c.currentLogger(false, nil).Debug("WBFT: changed state", "old.state", oldState.String(), "new.state", state.String())
	}
	if state == StateAcceptRequest {
		c.processPendingRequests()
	}

	// each time we change state, we process backlog for possible message that are
	// now ready
	c.processBacklog()
}

func PrepareSeal(header *types.Header, round uint32, sealType SealType) []byte {
	h := types.CopyHeader(header)
	roundHeader := h.WBFTHashWithRoundNumber(round).Bytes()
	return crypto.Keccak256Hash(append(roundHeader, byte(sealType))).Bytes()
}

func (c *Core) addToBacklog(msg wbfmessage.WBFTMessage) {
	logger := c.currentLogger(true, msg)

	src := msg.Source()
	if src == c.Address() {
		logger.Warn("WBFT: backlog from self")
		return
	}

	logger.Trace("WBFT: new backlog message", "backlogs_size", len(c.backlogs))

	c.backlogsMu.Lock()
	defer c.backlogsMu.Unlock()

	backlog := c.backlogs[src]
	if backlog == nil {
		backlog = prque.New[int64, wbfmessage.WBFTMessage](nil)
		c.backlogs[src] = backlog
	}
	view := msg.View()
	backlog.Push(msg, toNegatePriority(msg.Code(), &view))
}

func (c *Core) checkRequestMsg(request *Request) error {
	if request == nil || request.Proposal == nil {
		return errInvalidMessage
	}

	if c.current == nil {
		return errCurrentIsNil
	}

	if cmp := c.current.sequence.Cmp(request.Proposal.Number()); cmp > 0 {
		return errOldMessage
	} else if cmp < 0 {
		return errFutureMessage
	} else {
		return nil
	}
}

func (c *Core) handleRequest(request *Request) error {
	logger := c.currentLogger(true, nil)

	logger.Debug("WBFT: handle block proposal request")

	if err := c.checkRequestMsg(request); err != nil {
		if err == errInvalidMessage {
			logger.Error("WBFT: invalid request")
			return err
		}
		logger.Error("WBFT: unexpected request", "err", err, "number", request.Proposal.Number(), "hash", request.Proposal.Hash())
		return err
	}

	c.current.pendingRequest = request
	if c.state == StateAcceptRequest {
		if c.current.Round().Uint64() == 0 {
			// if round > 0, then we don't send preprepare because it would be failed due to having no justification
			// after that we will send preprepare when 2/3+ round change messages are received
			c.sendPreprepareMsg(request)
		}
	}

	return nil
}
